-- Aconchego – cardápio da noite (Menu PDF da casa + Aiqfome), tamanhos e adicionais por tamanho
alter table public.produtos add column if not exists variacoes jsonb not null default '[]'::jsonb; -- [{nome, preco}]
alter table public.adicionais add column if not exists preco_por_variacao jsonb; -- {"Grande (8 pedaços)": 10}
update public.categorias set ativo = false where slug in ('petiscos','sobremesas');
update public.categorias set turno = 'almoco' where slug = 'marmitex';
update public.configuracoes set mostrar_precos = true where id = 1;
select (select count(*) from public.produtos) produtos, (select count(*) from public.adicionais) adicionais, (select count(*) from public.categorias where ativo) categorias;
update public.faq set resposta = 'Sim. O Aconchego é choperia no almoço e à noite: chopp gelado com o almoço e, à noite, com pizza e porções no Bar Aconchego.' where pergunta = 'Tem chopp gelado?';
